// ---- Q1_D4: the same row-parallel gemv on nds.vd4dots.vv (XAndesVDot) ------
// Needs the Q1_D4 sign-plane order (repack.h q1_0x64_sign_bit) and
// -march=..._xandesvdot. Only the VLEN>=1024 shape is implemented: e32/m2 is
// then exactly 64 i32 lanes = 64 rows, and the same register group seen as i8
// is 256 bytes = 64 rows x 4 columns, which is the operand shape the
// instruction consumes. Everything else falls through to the generic kernel.
#if defined(Q1_D4) && Q1_D4

// vd[lane] += sum_{k<4} vs1[4*lane+k] * vs2[4*lane+k], int8 x int8 into i32.
// GCC 14.2 has no intrinsic, so this is inline asm - and that shapes the whole
// helper. Two consequences drive the design, both measured, both gated by
// ./check-vd4dots.sh:
//
// 1. vtype churn (F9). GCC cannot see inside an asm block, so it assumes every
//    block left vtype unknown and re-issues its own vsetvli before the next
//    intrinsic. A one-dot block therefore costs TWO vsetvli, and the kernels
//    also alternate between the byte view (mask load, sign expand) and the
//    32-bit view (broadcast, dot) - 4 vsetvli per dot in the first version,
//    40% of the gemv inner loop, none of it arithmetic. Grouping the two
//    widths in the SOURCE is not enough: the scheduler interleaves them again.
//    So everything at e32 lives inside one block - the broadcasts too - which
//    leaves GCC only e8 work to schedule and pays one vsetvli per four dots.
//
// 2. The broadcast must stay vmv.v.x. Handed the intrinsic, GCC contracts
//    "load a word, splat it" into `vlse32.v vd,(rs1),zero`, and a stride-0
//    strided load is element-serial on this core - 18x slower. Taking the
//    activation quads as plain uint32 GPRs and spelling the splat out here
//    makes that contraction impossible by construction.
//
// Two scratch vectors, not four, so the four dots still overlap while the
// register budget stays clear of the 4 accumulators the gemm needs.

// gemv: four (weight, activation) pairs chained into one accumulator
static inline vint32m2_t q1_vd4dots_x4_m2(vint32m2_t acc,
        vint8m2_t w0, vint8m2_t w1, vint8m2_t w2, vint8m2_t w3,
        uint32_t u0, uint32_t u1, uint32_t u2, uint32_t u3) {
    vint8m2_t s0, s1;
    asm volatile(
        "vsetvli t0, zero, e32, m2, ta, ma\n\t"
        "vmv.v.x %[s0], %[u0]\n\t"
        "vmv.v.x %[s1], %[u1]\n\t"
        "nds.vd4dots.vv %[acc], %[w0], %[s0]\n\t"
        "nds.vd4dots.vv %[acc], %[w1], %[s1]\n\t"
        "vmv.v.x %[s0], %[u2]\n\t"
        "vmv.v.x %[s1], %[u3]\n\t"
        "nds.vd4dots.vv %[acc], %[w2], %[s0]\n\t"
        "nds.vd4dots.vv %[acc], %[w3], %[s1]"
        : [acc] "+vr" (acc), [s0] "=&vr" (s0), [s1] "=&vr" (s1)
        : [w0] "vr" (w0), [w1] "vr" (w1), [w2] "vr" (w2), [w3] "vr" (w3),
          [u0] "r" (u0), [u1] "r" (u1), [u2] "r" (u2), [u3] "r" (u3)
        : "t0");
    return acc;
}

// gemm: one weight vector against the four output rows of the M-tile

